RULES = [(k, label, re.compile(rx)) for k, label, rx in RULES]
LABELS = {k: l for k, l, _ in RULES}
LABELS.update({'leadership': "Other politicians' leadership PACs", 'candidates': "Other candidates & joint fundraisers", 'party': 'Party committees', 'other_corp': 'Other corporate PACs', 'other_trade': 'Other trade associations', 'other_member': 'Other membership groups', 'other': 'Unclassified'})

def classify(cm):
    tp, dsgn = cm['tp'], cm['dsgn']
    if tp in ('X', 'Y', 'Z'): return 'party'
    if tp in ('H', 'S', 'P') or dsgn == 'J' or (cm['cand'] and dsgn in ('P', 'A')): return 'candidates'
    if dsgn == 'D' or 'LEADERSHIP FUND' in cm['name'].upper(): return 'leadership'
    if cm['org'] == 'L': return 'labor'
    text = (cm['conn'] + ' | ' + cm['name']).upper()
    for k, label, rx in RULES:
        if rx.search(text): return k
    return {'C': 'other_corp', 'T': 'other_trade', 'M': 'other_member', 'L': 'labor'}.get(cm['org'], 'other')


EMPLOYER_SPECIAL = [
    ('retired', 'Retired', re.compile(r'^(RETIRED|RETIRE|RET\.?|RETIREE)$')),
    ('self', 'Self-employed / small business', re.compile(r'SELF[- ]?EMPLOYED|SELF\b|SOLE PROPRIETOR|OWNER|FREELANCE|CONSULTANT$|INDEPENDENT CONTRACTOR|ENTREPRENEUR|INVESTOR$')),
    ('none', 'Not employed / not stated', re.compile(r'^(NOT EMPLOYED|UNEMPLOYED|NONE|N/A|NA|HOMEMAKER|HOUSEWIFE|STUDENT|INFORMATION REQUESTED.*|NOT APPLICABLE|NO EMPLOYER|DISABLED|VOLUNTEER)$')),
    ('gov', 'Government, education & nonprofits', re.compile(r'\b(UNIVERSITY|COLLEGE|SCHOOL|SCHOOLS|STATE OF|COUNTY|CITY OF|US ARMY|U\.S\. ARMY|NAVY|AIR FORCE|US GOVERNMENT|U\.S\. GOVERNMENT|FEDERAL GOVERNMENT|DEPARTMENT OF|US SENATE|U\.S\. SENATE|US HOUSE|CONGRESS|PUBLIC SCHOOL|NONPROFIT|NON-PROFIT|FOUNDATION|CHURCH|LIBRARY|VA\b|VETERANS AFFAIRS)\b')),
]

def classify_employer(name):
    """Tag a donor's employer string. Returns a key from LABELS or EMPLOYER_SPECIAL."""
    t = (name or '').strip().upper()
    if not t: return 'none'
    for k, label, rx in EMPLOYER_SPECIAL:
        if rx.search(t): return k
    for k, label, rx in RULES:
        if rx.search(t): return k
    return 'other'

EMP_LABELS = dict(LABELS)
EMP_LABELS.update({k: l for k, l, _ in EMPLOYER_SPECIAL})
EMP_LABELS['other'] = 'Other employers'
